	ngOnInit(): void {
		this.getBannerdata();
		this.loadLottieScript();
		if (!isPlatformBrowser(this.platformId)) {
			this.loadSecondaryContent();
			return;
		}

		if ('requestIdleCallback' in globalThis) {
			globalThis.requestIdleCallback(() => {
				this.loadSecondaryContent();
			});
			return;
		}

		setTimeout(() => {
			this.loadSecondaryContent();
		}, 1000);
	}

	loadSecondaryContent() {
		this.getFaqsData();
		this.getTestimonialsData();

		this.addSchema();
		this.addCollectionPageSchema();
		this.addBreadcrumbSchema();
		this.addDynamicSchema();
	}

	// Module 10 redesign — renders any agent-applied JSON-LD blocks (CollectionPage,
	// etc.) from PageSchema/Mongo, alongside the hardcoded blocks above.
	addDynamicSchema() {
		this.pageSchemaService.getPageSchema('services').subscribe((blocks) => {
			for (const block of blocks) {
				const existing = this.document.getElementById(`schema-agent-${block.schemaType}`);
				if (existing) existing.remove();
				const script = this.document.createElement('script');
				script.type = 'application/ld+json';
				script.id = `schema-agent-${block.schemaType}`;
				script.textContent = block.jsonLd;
				this.document.head.appendChild(script);
			}
		});
	}

	loadLottieScript() {
		if (isPlatformBrowser(this.platformId) && !this.document.getElementById('lottie-script')) {
			const script = this.document.createElement('script');
			script.id = 'lottie-script';
			script.src = '/lottie/lottie.js';
			script.async = true;
			script.onload = () => {
				// Trigger a change detection cycle once loaded to initialize any animations
				this.cdr.markForCheck();
			};
			this.document.body.appendChild(script);
		}
	}
