	ngAfterViewChecked() {
		if (!isPlatformBrowser(this.platformId) || typeof lottie === 'undefined') return;

		// Since the lottieContainer is inside dynamically injected innerHTML,
		// @ViewChildren won't find it and it might be destroyed/recreated by Angular's change detection.
		const elements = this.document.querySelectorAll('.lottieContainer');

		elements.forEach((el: any) => {
			// Only initialize if this specific DOM element hasn't been initialized yet
			if (!el.hasAttribute('data-lottie-init')) {
				const instance = lottie.loadAnimation({
					container: el,
					renderer: 'svg',
					loop: true,
					autoplay: true,
					animationData: this.animationData
				});
				this.lottieInstances.push(instance);
				el.setAttribute('data-lottie-init', 'true');
			}
		});
	}
	getBannerdata() {
		const obj = {
			userUrl: '/projects',
			btnContent: 'Explore Our Projects',
			btnContent_ar: 'استكشف مشاريعنا'
		};

		this.bannerService.getHomeBanner(obj).subscribe({
			next: (response: any) => {
				if (response?.code === 200 && response?.result?.length > 0) {
					this.bannerData = response.result
						.filter((item: any) => item.page === 'services-page')
						.map((item: any) => ({
							...item,
							userUrl: obj.userUrl,
							btnContent: obj.btnContent,
							btnContent_ar: obj.btnContent_ar
						}));

					this.hasBanner = this.bannerData.length > 0;
					this.cdr.markForCheck();
				}
			},
			error: (err) => {
				console.error('Banner API error:', err);
			}
		});
	}
